// Finds the warmest reading in a list of temperatures.
fun warmest(readings: List<Int>): Int {
    var best = readings[0]
    for (reading in readings) {
        if (reading > best) {
            best = reading
        }
    }
    return best
}

fun main() {
    println("Warmest: " + warmest(listOf(12, 18, 15)))
    println("Warmest: " + warmest(listOf(-8, -3, -6)))
}
